module parity_8bit (
    input [7:0] in,
    output out
);

wire [3:0] temp;
assign temp[0] = in[0] ^ in[1];
assign temp[1] = in[2] ^ in[3];
assign temp[2] = in[4] ^ in[5];
assign temp[3] = in[6] ^ in[7];
assign out = ^temp;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_sel0, not_sel1;
    wire term0, term1, term2, term3;

    // Invert select signals
    not (not_sel0, sel[0]);
    not (not_sel1, sel[1]);

    // Generate AND terms for each input
    and (term0, in[0], not_sel1, not_sel0);
    and (term1, in[1], not_sel1, sel[0]);
    and (term2, in[2], sel[1], not_sel0);
    and (term3, in[3], sel[1], sel[0]);

    // Combine all terms to get output
    or (out, term0, term1, term2, term3);

endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);

    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];

endmodule

