module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    if (in[3])
        code = 2'b11;
    else if (in[2])
        code = 2'b10;
    else if (in[1])
        code = 2'b01;
    else
        code = 2'b00;
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    localparam [1:0] GREEN  = 2'b00,
                     YELLOW = 2'b01,
                     RED    = 2'b10;

    reg [1:0] current_state, next_state;

    // State register
    always @(posedge clk) begin
        if (reset)
            current_state <= GREEN;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        if (reset)
            next_state = GREEN;
        else
            case (current_state)
                GREEN:  next_state = YELLOW;
                YELLOW: next_state = RED;
                RED:    next_state = GREEN;
                default: next_state = GREEN;
            endcase
    end

    // Output assignment
    assign state = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State definitions
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    reg [1:0] current_state, next_state;

    // State transition logic
    always @(posedge clk) begin
        if (reset)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    // Next state combinational logic
    always @(*) begin
        case (current_state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0; // Handle unexpected states
        endcase
    end

    // Output generation based on current state
    assign light = (current_state == S0) ? 3'b100 :
                      (current_state == S1) ? 3'b010 :
                      (current_state == S2) ? 3'b001 :
                      3'b000; // Default case

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

parameter S0 = 2'b00,
          S1 = 2'b01,
          S2 = 2'b10,
          S3 = 2'b11;

reg [1:0] current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset)
        current_state <= S0;
    else
        current_state <= next_state;
end

always @(*) begin
    case (current_state)
        S0: next_state = up_request ? S1 : S0;
        S1: next_state = up_request ? S3 : S2;
        S2: next_state = down_request ? S1 : S3;
        S3: next_state = down_request ? S2 : S0;
        default: next_state = S0;
    endcase
end

assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] FIRST_STATE  = 2'b00,
                     SECOND_STATE = 2'b01,
                     THIRD_STATE  = 2'b10,
                     FOURTH_STATE = 2'b11;

    reg [1:0] current_state, next_state;

    // State register with asynchronous reset
    always @(posedge clk, posedge reset) begin
        if (reset)
            current_state <= FIRST_STATE;
        else
            current_state <= next_state;
    end

    // Next state combinational logic
    always @(*) begin
        if (coin_inserted)
            next_state = THIRD_STATE;
        else if (item_selected)
            next_state = (current_state == FOURTH_STATE) ? FIRST_STATE : SECOND_STATE;
        else
            next_state = current_state;
    end

    // Output assignment
    assign state = current_state;

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    wire [7:0] stage1, stage2;

    // 1-bit left circular shift if shift[0] is set
    assign stage1 = shift[0] ? {in[6:0], in[7]} : in;

    // 2-bit left circular shift if shift[1] is set
    assign stage2 = shift[1] ? {stage1[5:0], stage1[7:6]} : stage1;

    // 4-bit left circular shift if shift[2] is set
    assign out = shift[2] ? {stage2[3:0], stage2[7:4]} : stage2;

endmodule

