module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    // Predefined 16-bit constants for musical notes (example values)
    reg [15:0] note0, note1, note2, note3, note4, note5, note6, note7;

    initial begin
        // Example initialization (replace with actual note values)
        note0 = 16'h0000; // Note 0
        note1 = 16'h0001; // Note 1
        note2 = 16'h0002; // Note 2
        note3 = 16'h0003; // Note 3
        note4 = 16'h0004; // Note 4
        note5 = 16'h0005; // Note 5
        note6 = 16'h0006; // Note 6
        note7 = 16'h0007; // Note 7
    end

    // Select the note based on shift (using modulo to handle 8 notes)
    wire [15:0] selected_note = note[shift];

    // Unfold the 16-bit constant into 8 bits for each output
    assign out[0] = selected_note[15];
    assign out[1] = selected_note[14];
    assign out[2] = selected_note[13];
    assign out[3] = selected_note[12];
    assign out[4] = selected_note[11];
    assign out[5] = selected_note[10];
    assign out[6] = selected_note[9];
    assign out[7] = selected_note[8];

endmodule

