module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg out_reg;

    always @(posedge clk) begin
        if (rst) begin
            out_reg <= 1'b0;
        end else begin
            out_reg <= ~out_reg;
        end
    end

    assign clk_out = out_reg;
