module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    assign eq = (a == b);
    assign lt = (a > b);
    assign gt = ~eq & ~lt;

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    assign out[0] = enable & ~in[1] & ~in[0];
    assign out[1] = enable & ~in[1] &  in[0];
    assign out[2] = enable &  in[1] & ~in[0];
    assign out[3] = enable &  in[1] &  in[0];

endmodule

