module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] count;

    always @(posedge clk) begin
        if (rst)
            count <= 8'd0;
        else
            count <= count + 8'd1;
    end

    assign count = (count >> 1) ^ count;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] temp_reg;

always @(posedge clk) begin
    if (rst) begin
        temp_reg <= 4'b0000;
    end else begin
        temp_reg <= { ~temp_reg[0], temp_reg[3:1] };
    end
end

assign q = temp_reg;

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

reg [7:0] shift_reg;

always @(posedge clk) begin
    if (rst)
        shift_reg <= 8'b0;
    else if (load)
        shift_reg <= pin;
    else
        shift_reg <= shift_reg >> 1;
end

assign sout = shift_reg[7];

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] state_reg;

always @(posedge clk) begin
    if (rst)
        state_reg <= 4'b0001;
    else
        state_reg <= {state_reg[2:0], state_reg[3]};
end

assign q = state_reg;

endmodule

module sipo_8bit(
