assign sout = shift_reg[0];

endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [3:0] tens_reg, units_reg;

always @(posedge clk) begin
    if (rst) begin
        tens_reg <= 4'd0;
        units_reg <= 4'd0;
    end else begin
        tens_reg <= (tens_reg == 4'd5) ? 4'd0 : tens_reg + 4'd1;
        units_reg <= (units_reg == 4'd9) ? 4'd0 : units_reg + 4'd1;
    end
end

assign count = {tens_reg, units_reg};

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] IDLE = 2'b00,
                   S1   = 2'b01,
                   S2   = 2'b10,
                   S3   = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge resetn) begin
    if (clk)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE: next_state = (r == 3'b101) ? S1 : IDLE;
      S1:   next_state = (r == 3'b111) ? S2 : S1;
      S2:   next_state = (r == 3'b101) ? S3 : S2;
      S3:   next_state = (r == 3'b111) ? IDLE : S3;
      default: next_state = IDLE;
    endcase
  end

  assign g = (current_state == S2) ? r : 3'b000;

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire t1, t2;

  assign t1 = (p1a & p1b) | (p1c & ~t1);
  assign t2 = (p1d & p1e) | (p1f & ~t2);
  assign p1y = t1 | t2;

  assign p2y = (p2a & p2b) | (p2c & p2d);

endmodule

