module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  parameter UP = 2'b10,
            RIGHT = 2'b01,
            DOWN = 2'b00,
            LEFT = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= UP;
    else
      current_state <= next_state;
  end

  always @(*) begin
    next_state = current_state;
    if (train_valid && train_taken) begin
      case (current_state)
        UP: next_state = RIGHT;
        DOWN: next_state = LEFT;
        RIGHT: next_state = DOWN;
        LEFT: next_state = UP;
        default: next_state = UP;
      endcase
    end
  end

  assign state = current_state;

endmodule

