  input [7:0] in,
  output reg [7:0] pedge
);

  reg [7:0] data_prev;
  wire [7:0] rising_edge;

  always @(posedge clk) begin
    data_prev <= in;
  end

  assign rising_edge = in & ~data_prev;

  always @(posedge clk) begin
    pedge <= rising_edge;
  end

endmodule

