module TopModule (
  input a,
  input b,
  input cin,
  output cout,
  output sum
);

  reg result;
  reg carry;

  always @(*) begin
    case ({a, cin})
      2'b00: result = b;
      2'b01, 2'b10: result = ~b;
      default: result = b;
    endcase

    if ((a == cin) && (b != a))
      carry = 1'b1;
    else
      carry = 1'b0;
  end

  assign sum = result;
  assign cout = carry;

endmodule

