  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] current_state, next_state;

  parameter [1:0] IDLE = 2'b00,
                  RUN  = 2'b01,
                  INC  = 2'b10,
                  DEC  = 2'b11;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = bump_left ? RUN : IDLE;
      RUN: begin
        if (bump_right & ground)
          next_state = INC;
        else if (bump_right & ~ground)
          next_state = DEC;
        else
          next_state = RUN;
      end
      INC: next_state = RUN;
      DEC: next_state = RUN;
      default: next_state = IDLE;
    endcase
  end

  // Output logic
  assign walk_left = (current_state == IDLE);
  assign walk_right = (current_state == RUN);
  assign aaah = (current_state == INC || current_state == DEC);

endmodule

