    WAITING_INPUT = 3'd0,
    PRESS_BUTTON  = 3'd1,
    WAITING_KEY   = 3'd2,
    RELEASE_KEY   = 3'd3,
    WAITING_LOW   = 3'd4,
    PRESS_AGAIN   = 3'd5,
    WAITING_HIGH  = 3'd6;

  reg [2:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (resetn)
      current_state <= WAITING_INPUT;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      WAITING_INPUT: 
        next_state = x ? PRESS_BUTTON : WAITING_INPUT;
      PRESS_BUTTON: 
        next_state = WAITING_KEY;
      WAITING_KEY: 
        next_state = y ? RELEASE_KEY : WAITING_KEY;
      RELEASE_KEY: 
        next_state = WAITING_LOW;
      WAITING_LOW: 
        next_state = (~x) ? PRESS_AGAIN : WAITING_LOW;
      PRESS_AGAIN: 
        next_state = WAITING_HIGH;
      WAITING_HIGH: 
        next_state = y ? RELEASE_KEY : WAITING_HIGH;
      default: 
        next_state = WAITING_INPUT;
    endcase
  end

  // Output logic
  assign f = (current_state == PRESS_AGAIN);
  assign g = (current_state == RELEASE_KEY);

endmodule

