module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Generate (G) and Propagate (P) signals for each bit
    wire [3:0] G = A & B;
    wire [3:0] P = A ^ B;

    // Carry Lookahead Logic
    assign A_less = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

    // Carry computation for each stage
    wire c1, c2, c3;
    assign c1 = G[0] | (P[0] & 1'b0);
    assign c2 = G[1] | (P[1] & G[0]) | (P[1] & P[0] & 1'b0);
    assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]) | (P[2] & P[1] & P[0] & 1'b0);

    // Sum computation
    assign A_equal = (P[3] ^ c3) & ~A_less;

    // Final A_greater calculation
    assign A_greater = A_equal | A_less;

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

reg prev_in;

always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		prev_in <= 1'b0;
		rise <= 1'b0;
		down <= 1'b0;
	end
	else begin
		// Store previous input value
		prev_in <= a;

		// Default outputs to 0
		rise <= 1'b0;
		down <= 1'b0;

		// Detect rising edge (0->1 transition)
		if (prev_in == 1'b0 && a == 1'b1) begin
			rise <= 1'b1;
		end
		// Detect falling edge (1->0 transition)
		else if (prev_in == 1'b1 && a == 1'b0) begin
			down <= 1'b1;
		end
	end
end

endmodule

