                 STATE1 = 3'b001,
                 STATE2 = 3'b010,
                 STATE3 = 3'b011,
                 STATE4 = 3'b100,
                 STATE5 = 3'b101;

reg [2:0] current_state, next_state;

// State transitions
always @(posedge CLK, posedge RST) begin
    if (RST) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end

// Next state logic
always @(*) begin
    if (IN) begin
        case (current_state)
            IDLE:   next_state = STATE1;
            STATE1: next_state = STATE2;
            STATE2: next_state = STATE3;
            STATE3: next_state = STATE4;
            STATE4: next_state = STATE5;
            STATE5: next_state = STATE5;
            default: next_state = IDLE;
        endcase
    end else begin
        next_state = current_state;
    end
end

// Output logic
always @(posedge CLK, posedge RST) begin
    if (RST) begin
        MATCH <= 1'b0;
    end else begin
        MATCH <= (current_state == STATE5);
    end
end

endmodule

